mapper.select:
select t.source_id from procurement_schema.purchase_order t
where t.source_system='SAP' and t.source_id>#{afterId} and t.source_id<=#{maxId}
  and not exists(select 1 from integration_schema.sync_reconciliation_seen s
    where s.run_id=#{runId} and s.source_id=t.source_id)
order by t.source_id limit #{limit}
